          }
          formatValue={formatConflictValue}
          onReapply={reapplyMyEdits}
        />
      )}

      {reappliedNotice && (
        <p role="status" data-testid="product-edit-reapplied" className="rounded-2xl border border-nw-border bg-nw-info-bg p-3 text-sm font-bold text-nw-info">
