        try {
          setStorefrontOffers(await fetchPublicStorefrontOffers());
          setOffersLoadError(null);
          lastLoadedAtRef.current.offers = Date.now();
        } catch (error) {
          console.error('[Storefront offers]', error);
          setOffersLoadError(
