                disabled={!canAdd}
                ariaLabel={`زيادة ${product.nameAr} في السلة`}
                className="w-full sm:hidden"
              />
              <div className="hidden h-11 items-center rounded-2xl border border-blue-200 bg-blue-50 sm:flex">
                <button
                  type="button"
                  onClick={() =>
                    onQuantityChange(product.id, cartQuantity - 1)
